// Reference implementation of a marko-ui component.
// Guide: /docs/creating-components · adapter internals: /docs/zag-adapter
// Authoring rules: notes/component-authoring.md (v2 pattern)
import * as switchMachine from "@zag-js/switch";
import type { MachineInput } from "marko-zag";
import { cn } from "../../../lib/utils.ts";
import { stripOwnProps } from "../../../lib/native-attrs.ts";

// MachineInput = native <input> attributes ∩ the machine's full Props, with
// `id` made optional (generated below, overridable). `checkedChange` is
// additive sugar enabling Marko's two-way bind shorthand
// (<Switch checked:=myState/>); Zag's own `onCheckedChange` also works and
// receives the details object.
export type Input = MachineInput<"input", switchMachine.Props> & {
  checkedChange?: (checked: boolean) => void;
  /**
   * Label text rendered after the control (Zag's `label` part), which also
   * becomes the accessible name of the hidden checkbox. Without it, pass
   * `aria-label` instead — a switch must have a name.
   */
  content?: Marko.Body;
  /**
   * Control size. Upstream (shadcn) styling API; the zag switch machine has
   * no `size` prop, so this is purely presentational — forwarded as
   * `data-size` on the control, not to the machine.
   */
  size?: "sm" | "default";
};

// The three-tag wiring (see /docs/creating-components):
// 1. <machine-props> picks the machine's props out of `input` by name and
//    merges the attributes written on it — callback adaptations live HERE,
//    visibly, because they are this component's public contract.
// 2. <service> creates and owns the running machine (client-only; SSR
//    renders from a throwaway never-started instance).
// 3. <connect> returns `api` as a GETTER — call it at every use site.
//    Getters are the serializable currency of Marko's resumability: the
//    api object itself must never become reactive state.
<machine-props/machineProps from=input pick=switchMachine.props
  onCheckedChange(details: switchMachine.CheckedChangeDetails) {
    input.onCheckedChange?.(details);
    input.checkedChange?.(details.checked);
  }/>
<service/service machine=() => switchMachine.machine props=machineProps/>
<connect/api=(service, normalizeProps) =>
  switchMachine.connect(service, normalizeProps)
  service=service
/>

// Whatever is neither machine-owned (splitProps) nor component-owned
// (class, checkedChange) passes through to the hidden input: aria-*,
// data-*, form attributes...
<const/nativeAttrs=(): Marko.HTMLAttributes<HTMLInputElement> =>
  stripOwnProps(
    switchMachine.splitProps(input)[1],
    "class",
    "checkedChange",
    "content",
    "size",
  )
>

// Zag always points the hidden input's aria-labelledby at the label part's
// id; when no label content is rendered that reference dangles and the
// switch ends up with NO accessible name (axe: label). Keep the reference
// only when the label part actually exists.
<const/hiddenInputProps=() => api().getHiddenInputProps()/>

<label
  ...api().getRootProps()
  data-slot="switch-label"
  class="inline-flex items-center gap-2"
>
  <span
    ...api().getControlProps()
    data-slot="switch"
    data-size=(input.size ?? "default")
    class=cn(
      "data-checked:bg-primary data-unchecked:bg-input focus-visible:border-ring focus-visible:ring-ring/30 aria-invalid:ring-destructive/20 dark:aria-invalid:ring-destructive/40 aria-invalid:border-destructive dark:aria-invalid:border-destructive/50 dark:data-unchecked:bg-input/80 shrink-0 rounded-full border border-transparent focus-visible:ring-2 aria-invalid:ring-2 data-[size=default]:h-[16.6px] data-[size=default]:w-[28px] data-[size=sm]:h-[14px] data-[size=sm]:w-[24px] peer group/switch relative inline-flex items-center transition-all outline-none after:absolute after:-inset-x-3 after:-inset-y-2 data-disabled:cursor-not-allowed data-disabled:opacity-50",
      input.class,
    )
  >
    <span
      ...api().getThumbProps()
      data-slot="switch-thumb"
      class="bg-background dark:data-unchecked:bg-foreground dark:data-checked:bg-primary-foreground rounded-full group-data-[size=default]/switch:size-3.5 group-data-[size=sm]/switch:size-3 group-data-[size=default]/switch:data-checked:translate-x-[calc(100%-2px)] group-data-[size=sm]/switch:data-checked:translate-x-[calc(100%-2px)] group-data-[size=default]/switch:data-unchecked:translate-x-0 group-data-[size=sm]/switch:data-unchecked:translate-x-0 pointer-events-none block ring-0 transition-transform"
    />
  </span>
  <if=input.content>
    <span
      ...api().getLabelProps()
      data-slot="switch-text"
      class="text-sm leading-none font-medium select-none peer-disabled:cursor-not-allowed peer-disabled:opacity-50"
    >
      <${input.content}/>
    </span>
  </if>
  <input
    ...nativeAttrs()
    ...hiddenInputProps()
    aria-labelledby=(input.content ? hiddenInputProps()["aria-labelledby"] : undefined)
  >
</label>

// Parents can receive the api getter: <Switch/switchApi/> then
// `switchApi().checked` — it stays live across machine updates.
<return=api>
